def t(lang, key):
    entry = STRINGS.get(key)
    if not entry:
        return key
    return entry.get(lang) or entry.get("es") or key


def dict_for(lang):
    """Devuelve {clave: texto} en el idioma dado (para exponer a JS)."""
    return {k: (v.get(lang) or v.get("es")) for k, v in STRINGS.items()}
